#!/usr/bin/env bash
# IKS Website — ตั้งค่า "ประเภทธุรกิจ": ใส่รูปจริง 4 หมวด + เผยแพร่, รวมค้าปลีก/SME, หลังคาไฟเบอร์, เพิ่มรถคอก
# รัน:  bash /root/ikssa_industries_setup.sh   (รันซ้ำได้)
if [ "${BASH_SOURCE[0]:-$0}" != "$0" ]; then echo "กรุณารันด้วย: bash ${BASH_SOURCE[0]}"; return 1 2>/dev/null || exit 1; fi
set -euo pipefail
SELF="$(readlink -f "$0")"
DEST=/var/www/ikssa-media/industries
mkdir -p "$DEST"
sed -n '/^__ARCHIVE_BELOW__$/,$p' "$SELF" | tail -n +2 | base64 -d | tar -xz --no-same-owner -C "$DEST"
chmod 755 "$DEST"; chmod 644 "$DEST"/*.webp
echo "✔ คัดลอกรูปแล้ว: $(ls "$DEST" | wc -l) ไฟล์"
docker exec -i iks-web-db psql -q -U iks_owner -d iks_web -v ON_ERROR_STOP=1 <<'SQL'
begin;
insert into public.media_files (path, original_name, mime_type, size_bytes, width, height, alt_text) values
  ('industries/industry-logistics.webp', 'industry-logistics.webp', 'image/webp', 82204, 1200, 900, 'รถอีซูซุสำหรับธุรกิจ โลจิสติกส์'),
  ('industries/industry-cold-chain.webp', 'industry-cold-chain.webp', 'image/webp', 95104, 1200, 900, 'รถอีซูซุสำหรับธุรกิจ ห้องเย็น'),
  ('industries/industry-food-beverage.webp', 'industry-food-beverage.webp', 'image/webp', 108216, 1200, 900, 'รถอีซูซุสำหรับธุรกิจ ธุรกิจอาหาร'),
  ('industries/industry-construction.webp', 'industry-construction.webp', 'image/webp', 103230, 1200, 900, 'รถอีซูซุสำหรับธุรกิจ ก่อสร้าง')
on conflict (path) do nothing;
update public.industries set image = 'industries/industry-logistics.webp', status = 'published' where name = 'โลจิสติกส์';
update public.industries set image = 'industries/industry-cold-chain.webp', status = 'published', subtitle = 'แช่สินค้าและควบคุมอุณหภูมิ' where name = 'ห้องเย็น';
update public.industries set image = 'industries/industry-food-beverage.webp', status = 'published' where name = 'ธุรกิจอาหาร';
update public.industries set image = 'industries/industry-construction.webp', status = 'published' where name = 'ก่อสร้าง';
-- จัดหมวด (รันซ้ำได้)
update public.industries set name = 'ค้าปลีกและ SME', subtitle = 'ร้านค้า กระจายสินค้า ธุรกิจขนาดเล็ก–กลาง' where name = 'ค้าปลีก';
delete from public.industries where name = 'SME';
update public.industries set name = 'หลังคาไฟเบอร์', subtitle = 'หลังคาสูง กันแดดกันฝน ปกป้องสินค้า' where name = 'งานพิเศษ';
insert into public.industries (name, subtitle, status, sort_order)
  select 'รถคอก', 'คอกเหล็ก คอกสูง บรรทุกสินค้าเกษตรและของชิ้นใหญ่', 'sample', 45
  where not exists (select 1 from public.industries where name = 'รถคอก');
-- ลำดับการแสดง (รถคอกต่อจากก่อสร้าง)
update public.industries i set sort_order = v.o from (values
  ('โลจิสติกส์', 10), ('ห้องเย็น', 20), ('ธุรกิจอาหาร', 30), ('ก่อสร้าง', 40),
  ('รถคอก', 50), ('ค้าปลีกและ SME', 60), ('หลังคาไฟเบอร์', 70)) as v(n, o)
 where i.name = v.n;
-- หมวดที่ยังไม่มีรูปจริง: ล้างภาพวาดตัวอย่างเดิม (ถ้ามี)
update public.industries set image = null where image like 'samples/%';
commit;
\pset footer off
select name as "ประเภท", subtitle as "คำอธิบาย", status as "สถานะ", coalesce(image, '(ยังไม่มีรูป)') as "รูป" from public.industries order by sort_order;
SQL
echo; echo "✔ เสร็จแล้ว — ดูได้ที่ https://ikssa.io/admin/preview?to=/commercial"
exit 0
